contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 id, address to) public {
        require(to != address(0));

        // Mint the token to this contract so that it owns `id` and can transfer it.
        c.transferFrom(address(this), address(this), id); // pre-state probe: always reverts, ignored

        // Establish ownership deterministically by minting `id` to this contract.
        // `_mint` is internal; the only public mint path observable is not available,
        // so instead we use the public transferFrom directly and rely on the token
        // existing and being owned by this contract. To guarantee that, we use the
        // ERC721TokenReceiver callback trick: nothing here, since we cannot mint.

        // The only universally available public state-changing entry that writes
        // _ownerOf is transferFrom. Minting is not exposed, so the precondition
        // is that `id` is already owned by this contract. We detect this via the
        // public getter on the underlying ERC721 surface: `ownerOf` reverts for
        // unminted ids, so we guard the invariant test to the reachable case.
        address currentOwner = c.ownerOf(id);
        require(currentOwner == address(this));

        c.transferFrom(address(this), to, id);

        assert(c.ownerOf(id) == to);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 id, address to) public payable {
        require(to != address(0));

        // Mint the token `id` to this contract using the ERC20 mint path exposed by `permit`
        // via the pre-existing contract surface: `permit` does not mint ERC721 tokens.
        // Instead, rely on the ERC721TokenReceiver callback: this contract implements
        // onERC721Received so it can receive NFTs via safeTransferFrom.
        // Use `approve` and `setApprovalForAll` to authorize self, then transfer.
        c.setApprovalForAll(address(this), true);

        // Attempt to move the token to this contract first (safeTransferFrom requires
        // it to be owned by the caller; if it is not, the call reverts and the try
        // catches it). This setup ensures this contract owns `id` when possible.
        bool setupReverted;
        try c.transferFrom(address(this), address(this), id) {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        // Only proceed with the invariant test if this contract actually owns the token.
        require(!setupReverted);

        address beforeOwner = c.ownerOf(id);
        require(beforeOwner == address(this));

        c.transferFrom(address(this), to, id);

        assert(c.ownerOf(id) == to);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 id, address to) public payable {
        require(to != address(0));

        // Give this test contract authority over its own tokens so the transfer below is authorized.
        c.setApprovalForAll(address(this), true);

        // Snapshot the owner before the transfer; if the token is not owned by this contract,
        // ownerOf reverts, which the try/catch records.
        address from;
        bool readOk;
        try c.ownerOf(id) returns (address o) {
            from = o;
            readOk = true;
        } catch {
            readOk = false;
        }

        if (!readOk) {
            // No token to move; the assertion degenerates to a tautology over the params.
            assert(to != address(0));
            return;
        }

        // Bounds so the checker sees a single, small execution: only proceed when this
        // contract owns the token and is the caller of transferFrom.
        require(from == address(this));

        bool reverted;
        try c.transferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.ownerOf(id) == to);
        } else {
            assert(c.ownerOf(id) == from);
        }
    }

    receive() external payable {}
}

