contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 id, address spender) public {
        // fresh c: mint token id to `from` through c's public mint entry
        c.acceptCounterOffer(
            C.Order({
                maker: from,
                isCall: false,
                isLong: false,
                baseAsset: address(0),
                strike: 0,
                premium: 0,
                duration: 0,
                expiration: block.timestamp + 1,
                nonce: id,
                whitelist: new address[](0),
                floorTokens: new address[](0),
                erc20Assets: new C.ERC20Asset[](0),
                erc721Assets: new C.ERC721Asset[](0)
            }),
            "",
            C.Order({
                maker: from,
                isCall: false,
                isLong: false,
                baseAsset: address(0),
                strike: 0,
                premium: 0,
                duration: 0,
                expiration: block.timestamp + 1,
                nonce: id,
                whitelist: new address[](0),
                floorTokens: new address[](0),
                erc20Assets: new C.ERC20Asset[](0),
                erc721Assets: new C.ERC721Asset[](0)
            })
        );

        // set an approval for the token to a non-zero spender
        c.approve(spender, id);

        // drive c through the public entry transferFrom; c's transferFrom requires msg.sender == from
        // so we send from == address(this) by construction of the fresh token ownership
        bool reverted;
        try c.transferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: whenever transferFrom succeeds, the approval for that id was cleared.
        assert(reverted || c.getApproved(id) == address(0));
    }

    receive() external payable {}
}

