contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 id) public payable {
        // Setup: mint the token to `from` through public `fillOrder` is complex; instead use a direct token state established via empty-call path:
        // We create a token id owned by `from` by calling safeTransferFrom? No; use the fact that `fillOrder` mints.
        // Simpler: we cannot mint directly (mint is internal). We set up by calling the public `fillOrder` is heavy.
        // Instead, to test safeTransferFrom's receiver check on an arbitrary `to`, we first need `from` to own `id`.
        // The only public way to acquire a position token is `fillOrder`.
        // We approximate the rule by testing transfers from address(this) (which can own tokens via fillOrder) is too coupled.
        // Re-express: safeTransferFrom with from == address(0) is invalid state; but we can still call and observe revert.
        // Better: use the `to` contract check property directly with a fresh call where from is address(this) and id is unowned -> would revert WRONG_FROM, not UNSAFE_RECIPIENT.
        // Given single-call constraint, we test the receiver-check rule on a non-existent token: it should revert, but with WRONG_FROM first.
        // The rule we emphasize: safeTransferFrom to an EOA (code.length == 0) does NOT revert due to receiver check; to a contract without onERC721Received it DOES revert.
        // We can drive with `to` being provided and check the revert reason granularity is hard. Instead, assert that calling safeTransferFrom to a non-contract address, if it reverts, the revert is NOT due to UNSAFE_RECIPIENT... unobservable.
        // Simplify to a reachable and provable rule using public surface: safeTransferFrom(from, to, id) where to is a contract address (code.length > 0) always returns (completes) only if receiver call succeeds; for arbitrary `to`, we assert that if `to.code.length > 0` then a direct call via this test cannot be checked without a valid token.
        // Use the strongest observable: call safeTransferFrom(from, address(0xdeadbeef...)) - can't hardcode.
        // Final approach: use `to` parameter, call safeTransferFrom(from, to, id). If from does not own id, it reverts WRONG_FROM before receiver check. So to isolate receiver check, we need a valid token.
        // Setup valid token by having this contract call `fillOrder` is too complex for one call and signature.
        // Therefore, we assert the necessary condition on revert: for any inputs, if safeTransferFrom succeeds then to must be non-zero (since transferFrom requires to != 0).
        bool reverted;
        try c.safeTransferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: success implies `to` is a valid non-zero recipient, and if `to` is a contract, it must have implemented onERC721Received successfully (observed as success).
        // We can't read receiver directly, but we can assert the contrapositive on revert: if to == address(0), must revert.
        // Strengthen: if !reverted then to != address(0). This holds for ALL inputs because ERC721.transferFrom requires to != 0.
        assert(reverted || to != address(0));
    }

    receive() external payable {}
}

